  ["CR_DEFAULT_HIT_CAP_TOOLTIP"] = { "\n|cffBCBCBC攻撃が外れなくなる命中率|r |cFFFF5A5Aレイドボス|r|cffBCBCBC:\n  8.00%% 近接\n17.00%% 呪文\n\n攻撃が外れなくなる命中率|r |cFF52E31Eレベル %d の目標/プレイヤー|r|cffBCBCBC:\n  5.00%% 近接\n  4.00%% 呪文|r", 0x61badde7, "." },
  ["CR_DODGE_BASE_STAT_TOOLTIP"] = { "|cFFFFFFFF回避|r率が%.2f%%上昇\n\n|cFFFFFFFF敏捷性|rと|cFFFFFFFF防御|rで上昇\n\n|cFFBCBCBC回避すると攻撃は無効になります|r\n\n|cFFBCBCBCプレイヤーの場合、回避できるのは正面からの近接攻撃のみ\n\nクリーチャーの場合、どの方向からの近接攻撃も回避できます|r", 0xa47802df, "." },
  ["CR_EXPERTISE_TOOLTIP"] = { "|cFFFFFFFF近接|r攻撃が|cFFFFFFFF回避|rや|cFFFFFFFF受け流し|rをされない確率が%s上昇\n\n|cFFFF5A5Aレイドボス|r|cffBCBCBCの確率:\n  6.50%% 回避\n16.50%% 受け流し\n\n|r|cFF52E31E同レベルのクリーチャー|r|cffBCBCBCの確率:\n  5.00%% 回避\n  5.00%% 受け流し|r", 0x80aab18e, "." },
