  ["CurrencyCategory:273"] = { "専門技能＆製作", 0xa443ef2a, "." },
  ["CurrencyDescription:1792"] = { "名誉は、PvP戦闘で敵対勢力のメンバーを倒すと獲得できます。名誉ポイントを使って特別なアイテムを購入できます。", 0xdcfb3ea8, "." },
  ["CurrencyDescription:3402"] = { "かなりの額のゴールドに相当するため、取引の盛んな商人組織の間で暫定的な通貨として使われています。Durotar Supply and LogisticsやAzeroth Commerce Authorityのメンバーなら、これと引き換えに取引に応じてくれるでしょう。", 0xab4f48ae, "." },
  ["CurrencyDescription:3468"] = { "ランクポイントは、Gadgetzanで与えられる任務を達成するか、戦場に参加すると獲得できます。ランクポイントによってPvPランクが上がり、特別なアイテムを購入できるようになります。", 0xa7e22a48, "." },
  ["CurrencyDescription:3469"] = { "この通貨は徐々に流通から外されつつありますが、Eastern KingdomsとKalimdor各地のゴブリンの町では、今も非常に有利なレートで交換できます。", 0x15a0429b, "." },
  ["CurrencyDescription:515"] = { "Darkmoon Faireでゲームに勝ったり頼みごとを引き受けたりすると授与されます。", 0xa7f0a300, "." },
